ALTER TABLE appointments ADD COLUMN token_count int NOT NULL DEFAULT 0 CHECK(token_count>=0),ADD COLUMN token_references jsonb NOT NULL DEFAULT '[]',ADD COLUMN authorization_expires date,ADD COLUMN token_requested_at timestamptz,ADD COLUMN signature_requested_at timestamptz,ADD COLUMN contested_at timestamptz,ADD COLUMN contest_reason text,ADD COLUMN contest_resolved_at timestamptz,ADD COLUMN contest_resolution text,ADD COLUMN financial_hold boolean NOT NULL DEFAULT false,ADD COLUMN absence_kind text NOT NULL DEFAULT 'PATIENT' CHECK(absence_kind IN('PATIENT','PROFESSIONAL')),ADD COLUMN appointment_kind text NOT NULL DEFAULT 'SESSION' CHECK(appointment_kind IN('SESSION','EVALUATION','REPLACEMENT','ANTICIPATION')),ADD COLUMN assistant_names text[] NOT NULL DEFAULT '{}',ADD COLUMN replacement_credit_id uuid,ADD COLUMN original_appointment_id uuid;
ALTER TABLE documents ADD COLUMN professional_id uuid,ADD COLUMN document_kind text NOT NULL DEFAULT 'GENERAL',ADD FOREIGN KEY(tenant_id,professional_id) REFERENCES professionals(tenant_id,id);
CREATE TABLE session_credits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,patient_id uuid NOT NULL,insurer_id uuid NOT NULL,source_appointment_id uuid NOT NULL,replacement_appointment_id uuid,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','RESERVED','USED','CANCELLED')),reason text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),used_at timestamptz,FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id),FOREIGN KEY(tenant_id,insurer_id) REFERENCES insurers(tenant_id,id),FOREIGN KEY(tenant_id,source_appointment_id) REFERENCES appointments(tenant_id,id),FOREIGN KEY(tenant_id,replacement_appointment_id) REFERENCES appointments(tenant_id,id),UNIQUE(tenant_id,source_appointment_id),UNIQUE(tenant_id,replacement_appointment_id),UNIQUE(tenant_id,id));
ALTER TABLE appointments ADD FOREIGN KEY(tenant_id,replacement_credit_id) REFERENCES session_credits(tenant_id,id),ADD FOREIGN KEY(tenant_id,original_appointment_id) REFERENCES appointments(tenant_id,id);
CREATE TABLE operation_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,appointment_id uuid,professional_id uuid,kind text NOT NULL CHECK(kind IN('TOKEN','SIGNATURE','REMINDER','EVOLUTION','WAITLIST','PAYOUT')),status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','SENT_MANUALLY','DONE')),message text NOT NULL,reference text,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz,FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,appointment_id) REFERENCES appointments(tenant_id,id),FOREIGN KEY(tenant_id,professional_id) REFERENCES professionals(tenant_id,id),UNIQUE(tenant_id,id));
CREATE UNIQUE INDEX operation_request_pending ON operation_requests(tenant_id,appointment_id,kind) WHERE appointment_id IS NOT NULL AND status='DRAFT';
CREATE TABLE signature_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,appointment_id uuid NOT NULL,token_hash text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','SIGNED','CANCELLED')),expires_at timestamptz NOT NULL,signer_name text,consent text,signature_svg text,signed_at timestamptz,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,appointment_id) REFERENCES appointments(tenant_id,id),UNIQUE(tenant_id,id));
CREATE SEQUENCE billing_batch_sequence;
CREATE TABLE billing_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,insurer_id uuid NOT NULL,number text NOT NULL DEFAULT ('LT-'||lpad(nextval('billing_batch_sequence')::text,6,'0')),status text NOT NULL DEFAULT 'PREPARED' CHECK(status IN('PREPARED','SENT','RETURNED')),amount numeric(12,2) NOT NULL CHECK(amount>0),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),sent_by uuid REFERENCES users(id),sent_at timestamptz,protocol text,FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,insurer_id) REFERENCES insurers(tenant_id,id),UNIQUE(tenant_id,number),UNIQUE(tenant_id,id));
CREATE TABLE billing_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),batch_id uuid NOT NULL,appointment_id uuid NOT NULL,amount numeric(12,2) NOT NULL CHECK(amount>0),snapshot jsonb NOT NULL,status text NOT NULL DEFAULT 'WAITING' CHECK(status IN('WAITING','PAID','PARTIAL','DENIED')),paid_amount numeric(12,2) NOT NULL DEFAULT 0 CHECK(paid_amount>=0),denial_reason text,return_reference text,returned_at timestamptz,FOREIGN KEY(tenant_id,batch_id) REFERENCES billing_batches(tenant_id,id),FOREIGN KEY(tenant_id,appointment_id) REFERENCES appointments(tenant_id,id),UNIQUE(tenant_id,appointment_id),UNIQUE(tenant_id,id));
CREATE TABLE billing_returns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),batch_id uuid NOT NULL,reference text NOT NULL,received_at date NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,batch_id) REFERENCES billing_batches(tenant_id,id),UNIQUE(tenant_id,batch_id,reference));
CREATE TRIGGER protect_billing_returns BEFORE UPDATE OR DELETE ON billing_returns FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TABLE waitlist(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,patient_id uuid NOT NULL,specialty text NOT NULL,preferred_days int[] NOT NULL DEFAULT '{}',preferred_period text NOT NULL DEFAULT 'ANY' CHECK(preferred_period IN('ANY','MORNING','AFTERNOON')),status text NOT NULL DEFAULT 'WAITING' CHECK(status IN('WAITING','OFFERED','SCHEDULED','CANCELLED')),priority text NOT NULL DEFAULT 'NORMAL' CHECK(priority IN('NORMAL','HIGH')),notes text NOT NULL DEFAULT '',appointment_id uuid,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id),FOREIGN KEY(tenant_id,appointment_id) REFERENCES appointments(tenant_id,id),UNIQUE(tenant_id,id));
CREATE UNIQUE INDEX waitlist_open_entry ON waitlist(tenant_id,patient_id,specialty) WHERE status IN('WAITING','OFFERED');
CREATE TABLE clinic_settings(tenant_id uuid PRIMARY KEY REFERENCES tenants(id),value jsonb NOT NULL DEFAULT '{}',version int NOT NULL DEFAULT 1,updated_by uuid REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE patient_assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),patient_id uuid NOT NULL,specialty text NOT NULL,target_sessions int NOT NULL CHECK(target_sessions BETWEEN 1 AND 100),completed_sessions int NOT NULL DEFAULT 0 CHECK(completed_sessions>=0),status text NOT NULL DEFAULT 'IN_PROGRESS' CHECK(status IN('IN_PROGRESS','COMPLETED','CANCELLED')),notes text NOT NULL DEFAULT '',created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id),UNIQUE(tenant_id,id));
CREATE TABLE patient_transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),patient_id uuid NOT NULL,from_professional_id uuid NOT NULL,to_professional_id uuid NOT NULL,reason text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,patient_id) REFERENCES patients(tenant_id,id),FOREIGN KEY(tenant_id,from_professional_id) REFERENCES professionals(tenant_id,id),FOREIGN KEY(tenant_id,to_professional_id) REFERENCES professionals(tenant_id,id));
CREATE TRIGGER protect_patient_transfers BEFORE UPDATE OR DELETE ON patient_transfers FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TABLE professional_absences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,professional_id uuid NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,reason text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at),FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,professional_id) REFERENCES professionals(tenant_id,id));
ALTER TABLE payout_reviews DROP CONSTRAINT payout_reviews_status_check,ADD CONSTRAINT payout_reviews_status_check CHECK(status IN('SENT','CONFIRMED','CONTESTED','APPROVED'));
CREATE TABLE payout_adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL,professional_id uuid NOT NULL,amount numeric(12,2) NOT NULL CHECK(amount<>0),reason text NOT NULL,ledger_id uuid,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id),FOREIGN KEY(tenant_id,professional_id) REFERENCES professionals(tenant_id,id),FOREIGN KEY(tenant_id,ledger_id) REFERENCES ledger(tenant_id,id),UNIQUE(tenant_id,id));
CREATE INDEX requests_unit_pending ON operation_requests(tenant_id,unit_id,status,created_at);
CREATE INDEX batch_unit ON billing_batches(tenant_id,unit_id,created_at);
